"""OCC report rendering helpers for P0."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from jinja2 import Environment, FileSystemLoader

DISCLAIMER_TEXT = (
    "This validation report is generated by an analytical workbench for model risk "
    "and fair-lending **review support**. It does not constitute legal advice, "
    "a regulatory filing, or a determination of compliance with any applicable law."
)

LIMITATIONS_TEXT = (
    "**Demo limitations:** This validation uses the UCI German Credit dataset "
    "(German domestic credit, circa 1990s). It does not represent US lending "
    "populations. No race/ethnicity fields are available; BISG proxy analysis is "
    "**not performed**. Population drift is **injected covariate shift** for "
    "pedagogical demonstration, not observed production drift. State overlay toggles "
    "(P3) illustrate jurisdictional framing only."
)


@dataclass(slots=True)
class ReportArtifacts:
    markdown_path: Path
    report_json_path: Path
    appendix_b_path: Path
    appendix_e_path: Path


def generate_occ_report(
    *,
    artifact_dir: Path,
    run_context: dict[str, Any],
    bias_summary: dict[str, Any],
    audit_summary: dict[str, Any],
) -> ReportArtifacts:
    artifact_dir.mkdir(parents=True, exist_ok=True)
    appendix_b_path = artifact_dir / "bias_battery_summary.json"
    appendix_b_path.write_text(json.dumps(bias_summary, indent=2, sort_keys=True))

    appendix_e_path = artifact_dir / "audit_chain_verification.json"
    appendix_e_path.write_text(json.dumps(audit_summary, indent=2, sort_keys=True))

    template_dir = Path(__file__).resolve().parent / "templates" / "occ_2026_13"
    env = Environment(
        loader=FileSystemLoader(template_dir),
        autoescape=False,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    template = env.get_template("report.md.j2")
    markdown = template.render(
        context=run_context,
        disclaimer=DISCLAIMER_TEXT,
        limitations=LIMITATIONS_TEXT,
    )

    markdown_path = artifact_dir / "german_credit_validation_report.md"
    markdown_path.write_text(markdown.strip() + "\n")

    report_json = {
        "run_context": run_context,
        "disclaimer": DISCLAIMER_TEXT,
        "limitations": LIMITATIONS_TEXT,
        "appendices": {
            "A": "Not applicable in P0",
            "B": str(appendix_b_path),
            "C": "Not run — drift module disabled",
            "D": "Not applicable in P0",
            "E": str(appendix_e_path),
        },
    }
    report_json_path = artifact_dir / "report.json"
    report_json_path.write_text(json.dumps(report_json, indent=2, sort_keys=True))

    return ReportArtifacts(
        markdown_path=markdown_path,
        report_json_path=report_json_path,
        appendix_b_path=appendix_b_path,
        appendix_e_path=appendix_e_path,
    )
